import math as m

def absorbance(transmission):
    return -m.log10(transmission)

print(absorbance(0.5))
print(absorbance(0.1))

temperature = 25
if temperature < 0:
    print("Température négative")
elif temperature == 0:
    print("Température nulle")
else:
    print("Température positive")
